 use serde :: { Deserialize , Serialize } ; use std :: collections :: HashMap ; # [doc = " Main entry point for eager splitting of a crate"] pub fn eager_split_crate (paths : & CratePaths , config : & SplitDeclsConfig) -> Result < () > { println ! ("📖 Parsing lib.rs...") ; let lib_content = fs :: read_to_string (& paths . lib_rs_path) . context (format ! ("Failed to read {}" , paths . lib_rs_path . display ())) ? ; println ! ("🔧 Parsing {} bytes of Rust code..." , lib_content . len ()) ; let syntax_tree : syn :: File = syn :: parse_file (& lib_content) . context ("Failed to parse lib.rs as Rust code") ? ; split_and_generate_decls (& syntax_tree , paths , config , false) ? ; generate_output_lib_rs (paths) ? ; generate_new_lib_rs (paths) ? ; generate_new_build_rs (paths) ? ; println ! ("Eager splitting completed for crate: {}" , paths . crate_name) ; println ! ("Output generated in: {}" , paths . decls_output_dir . parent () . unwrap () . display ()) ; Ok (()) }